package com.lawdesk.cases;

import java.math.BigDecimal;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

import com.lawdesk.api.PageResponse;

/**
 * SQL access to {@code legal_case} and {@code case_reference_counter}. Plain JDBC keeps identifiers, defaults and
 * timestamps generated by the database (architecture/CONTRACTS.md §2).
 */
@Repository
class CaseRepository {

    private static final String COLUMNS = """
            id, reference_no, title, case_type, subject, opened_on, status, version, created_at, created_by,
            updated_at, updated_by, automated_no, authority_position, financial_impact, financial_amount,
            primary_member_id, alternate_member_id, confidentiality, owning_unit_id,
            chamber, received_on, referring_unit_id, referred_by, facts, claimed_amount, importance, internal_notes,
            (select display_name from app_user where id = primary_member_id) as primary_member_name,
            (select display_name from app_user where id = alternate_member_id) as alternate_member_name""";

    private static final Map<String, String> SORT_COLUMNS = Map.of(
            "referenceNo", "reference_no",
            "title", "title",
            "openedOn", "opened_on",
            "status", "status",
            "createdAt", "created_at",
            "updatedAt", "updated_at");

    private final JdbcClient jdbc;

    CaseRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    LegalCase insert(String referenceNo, String title, CaseType caseType, String subject, LocalDate openedOn,
            UUID actor) {
        return jdbc.sql("""
                        insert into legal_case (reference_no, title, case_type, subject, opened_on, created_by,
                                                updated_by, owning_unit_id)
                        values (:referenceNo, :title, :caseType, :subject, :openedOn, :actor, :actor,
                                (select org_unit_id from app_user where id = :actor))
                        returning\s""" + COLUMNS)
                .param("referenceNo", referenceNo).param("title", title).param("caseType", caseType.name())
                .param("subject", subject).param("openedOn", openedOn).param("actor", actor)
                .query(CaseRepository::row).single();
    }

    /** A case registered through the government intake: the legacy columns plus the intake ones (LD-045). */
    LegalCase insertIntake(String referenceNo, String automatedNo, String title, CaseType caseType, String subject,
            LocalDate openedOn, Side authorityPosition, FinancialImpact impact, BigDecimal amount, UUID actor) {
        return jdbc.sql("""
                        insert into legal_case (reference_no, automated_no, title, case_type, subject, opened_on,
                                                authority_position, financial_impact, financial_amount, created_by,
                                                updated_by, owning_unit_id)
                        values (:referenceNo, :automatedNo, :title, :caseType, :subject, :openedOn, :position,
                                :impact, :amount, :actor, :actor, (select org_unit_id from app_user where id = :actor))
                        returning\s""" + COLUMNS)
                .param("referenceNo", referenceNo).param("automatedNo", automatedNo).param("title", title)
                .param("caseType", caseType.name()).param("subject", subject).param("openedOn", openedOn)
                .param("position", authorityPosition.name()).param("impact", impact.name()).param("amount", amount)
                .param("actor", actor)
                .query(CaseRepository::row).single();
    }

    /** What an edit may change besides the legacy fields; a null value leaves the column alone (LD-045). */
    record DetailsChange(String automatedNo, FinancialImpact impact, BigDecimal amount, CaseDetails details) {
    }

    /**
     * Applies an edit if {@code expectedVersion} is still current and the case is not read-only; empty otherwise, so
     * the caller cannot overwrite a change it has not seen.
     */
    Optional<LegalCase> update(UUID id, long expectedVersion, String title, CaseType caseType, String subject,
            LocalDate openedOn, DetailsChange change, UUID actor) {
        return jdbc.sql("""
                        update legal_case
                        set title = :title, case_type = :caseType, subject = :subject, opened_on = :openedOn,
                            automated_no = coalesce(cast(:automatedNo as varchar), automated_no),
                            financial_impact = coalesce(cast(:impact as varchar), financial_impact),
                            financial_amount = case when cast(:impact as varchar) is null then financial_amount
                                                    when cast(:impact as varchar) = 'NO' then null
                                                    else cast(:amount as numeric) end,
                            chamber = case when :replace then :chamber else chamber end,
                            received_on = case when :replace then :receivedOn else received_on end,
                            referring_unit_id = case when :replace then :referringUnit else referring_unit_id end,
                            referred_by = case when :replace then :referredBy else referred_by end,
                            facts = case when :replace then :facts else facts end,
                            claimed_amount = case when :replace then :claimed else claimed_amount end,
                            importance = case when :replace then :importance else importance end,
                            internal_notes = case when :replace then :notes else internal_notes end,
                            version = version + 1, updated_at = now(), updated_by = :actor
                        where id = :id and version = :version and status not in ('CLOSED', 'ARCHIVED')
                        returning\s""" + COLUMNS)
                .param("id", id).param("version", expectedVersion).param("title", title)
                .param("caseType", caseType.name()).param("subject", subject).param("openedOn", openedOn)
                .param("automatedNo", change.automatedNo())
                .param("impact", change.impact() == null ? null : change.impact().name())
                .param("amount", change.amount()).param("actor", actor)
                .param("replace", change.details() != null)
                .param("chamber", d(change.details()).chamber()).param("receivedOn", d(change.details()).receivedOn())
                .param("referringUnit", d(change.details()).referringUnitId())
                .param("referredBy", d(change.details()).referredBy()).param("facts", d(change.details()).facts())
                .param("claimed", d(change.details()).claimedAmount())
                .param("importance", d(change.details()).importance())
                .param("notes", d(change.details()).internalNotes())
                .query(CaseRepository::row).optional();
    }

    private static CaseDetails d(CaseDetails details) {
        return details == null ? CaseDetails.EMPTY : details;
    }

    /** Sets the details of the case just registered, in the same transaction; no version change. */
    void setDetails(UUID id, CaseDetails details) {
        if (details.isEmpty()) {
            return;
        }
        jdbc.sql("""
                        update legal_case set chamber = :chamber, received_on = :receivedOn,
                            referring_unit_id = :referringUnit, referred_by = :referredBy, facts = :facts,
                            claimed_amount = :claimed, importance = :importance, internal_notes = :notes
                        where id = :id""")
                .param("id", id).param("chamber", details.chamber()).param("receivedOn", details.receivedOn())
                .param("referringUnit", details.referringUnitId()).param("referredBy", details.referredBy())
                .param("facts", details.facts()).param("claimed", details.claimedAmount())
                .param("importance", details.importance()).param("notes", details.internalNotes()).update();
    }

    /** The members of a case, or empty when there is no such case. */
    record Assignment(UUID primary, UUID alternate) {

        boolean isMember(UUID user) {
            return user != null && (user.equals(primary) || user.equals(alternate));
        }
    }

    Optional<Assignment> assignment(UUID id) {
        return jdbc.sql("select primary_member_id, alternate_member_id from legal_case where id = :id").param("id", id)
                .query((rs, n) -> new Assignment(rs.getObject("primary_member_id", UUID.class),
                        rs.getObject("alternate_member_id", UUID.class)))
                .optional();
    }

    /** Sets the members if {@code expectedVersion} is still current; empty otherwise. */
    Optional<LegalCase> assign(UUID id, long expectedVersion, UUID primary, UUID alternate, UUID actor) {
        return jdbc.sql("""
                        update legal_case
                        set primary_member_id = :primary, alternate_member_id = :alternate, version = version + 1,
                            owning_unit_id = coalesce((select org_unit_id from app_user where id = :primary),
                                                      owning_unit_id),
                            updated_at = now(), updated_by = :actor
                        where id = :id and version = :version
                        returning\s""" + COLUMNS)
                .param("id", id).param("version", expectedVersion).param("primary", primary)
                .param("alternate", alternate).param("actor", actor)
                .query(CaseRepository::row).optional();
    }

    /** Intake only: sets the members of the case just registered, in the same transaction. */
    void assignNew(UUID id, UUID primary, UUID alternate) {
        jdbc.sql("""
                        update legal_case set primary_member_id = :primary, alternate_member_id = :alternate,
                            owning_unit_id = coalesce((select org_unit_id from app_user where id = :primary),
                                                      owning_unit_id)
                        where id = :id""")
                .param("id", id).param("primary", primary).param("alternate", alternate).update();
    }

    /** Moves the case from {@code from} to {@code to} if {@code expectedVersion} is still current; empty otherwise. */
    Optional<LegalCase> changeStatus(UUID id, long expectedVersion, CaseStatus from, CaseStatus to, UUID actor) {
        return jdbc.sql("""
                        update legal_case
                        set status = :to, version = version + 1, updated_at = now(), updated_by = :actor
                        where id = :id and version = :version and status = :from
                        returning\s""" + COLUMNS)
                .param("id", id).param("version", expectedVersion).param("from", from.name())
                .param("to", to.name()).param("actor", actor)
                .query(CaseRepository::row).optional();
    }

    PageResponse<CaseListItem> search(CaseSearch search, CaseAccessPolicy.Predicate visible) {
        StringBuilder where = new StringBuilder(" where " + visible.sql());
        Map<String, Object> params = new HashMap<>(visible.params());
        if (search.q() != null) {
            // Section 1: by case number (internal, judicial automated or court number), subject, opponent, member or
            // involved employee and unit.
            // The trigram prefilter (V801) narrows the cases first, but only when it is selective (a broad text is just as well read in one pass). When it leaves few, the related tables are tested for those
            // cases only (a correlated EXISTS on an indexed case_id); when it leaves many, each related table is read once into a
            // hashed set (an uncorrelated IN), which was what made the same search over 50 000 cases take seconds before
            // (LD-058 performance run). Both forms select exactly the same cases.
            boolean fewCandidates = Text.fewTrigramCandidates(jdbc, search.q());
            if (fewCandidates) {
                where.append(Text.trigramPrefilter(search.q(), "c.id", "qraw"));
                params.put("qraw", search.q());
            }
            String related = fewCandidates
                    ? " or exists (select 1 from case_party cp join party p on p.id = cp.party_id where cp.case_id = c.id"
                            + " and p.name ilike :q escape '\\')"
                    + " or exists (select 1 from proceeding pr where pr.case_id = c.id and pr.court_case_number ilike :q escape '\\')"
                    + " or c.primary_member_id in (select m.id from app_user m where m.display_name ilike :q escape '\\')"
                    + " or c.alternate_member_id in (select m.id from app_user m where m.display_name ilike :q escape '\\')"
                    + " or exists (select 1 from case_org_involvement i where i.case_id = c.id and i.removed_at is null"
                    + " and (i.contact_name ilike :q escape '\\' or i.sector_name_snapshot ilike :q escape '\\'"
                    + " or i.department_name_snapshot ilike :q escape '\\' or i.section_name_snapshot ilike :q escape '\\'))"
                    : " or c.id in (select cp.case_id from case_party cp join party p on p.id = cp.party_id"
                    + " where p.name ilike :q escape '\\')"
                    + " or c.id in (select pr.case_id from proceeding pr where pr.court_case_number ilike :q escape '\\')"
                    + " or c.primary_member_id in (select m.id from app_user m where m.display_name ilike :q escape '\\')"
                    + " or c.alternate_member_id in (select m.id from app_user m where m.display_name ilike :q escape '\\')"
                    + " or c.id in (select i.case_id from case_org_involvement i where i.removed_at is null"
                    + " and (i.contact_name ilike :q escape '\\' or i.sector_name_snapshot ilike :q escape '\\'"
                    + " or i.department_name_snapshot ilike :q escape '\\' or i.section_name_snapshot ilike :q escape '\\'))";
            where.append(" and (reference_no ilike :q escape '\\' or title ilike :q escape '\\'"
                    + " or subject ilike :q escape '\\' or automated_no ilike :q escape '\\'" + related + ")");
            params.put("q", "%" + Text.escapeLike(search.q()) + "%");
        }
        if (!search.status().isEmpty()) {
            where.append(" and status in (:status)");
            params.put("status", search.status().stream().map(Enum::name).toList());
        }
        if (!search.caseType().isEmpty()) {
            where.append(" and case_type in (:caseType)");
            params.put("caseType", search.caseType().stream().map(Enum::name).toList());
        }
        if (search.openedFrom() != null) {
            where.append(" and opened_on >= :openedFrom");
            params.put("openedFrom", search.openedFrom());
        }
        if (search.openedTo() != null) {
            where.append(" and opened_on <= :openedTo");
            params.put("openedTo", search.openedTo());
        }
        int page = search.pageOrDefault();
        int size = search.sizeOrDefault();
        params.put("limit", size);
        params.put("offset", (long) page * size);
        // The page and the total come from one pass over the register (count(*) over ()); a second pass for the count
        // doubled the time of every list (LD-058 performance run). Only a page past the end needs the count on its own.
        long[] counted = {-1};
        List<CaseListItem> items = jdbc.sql("""
                        select id, reference_no, title, case_type, status, opened_on, updated_at, count(*) over () as total
                        from legal_case c""" + where + orderBy(search.sort()) + " limit :limit offset :offset")
                .params(params)
                .query((rs, rowNum) -> {
                    counted[0] = rs.getLong("total");
                    return new CaseListItem(
                        rs.getObject("id", UUID.class),
                        rs.getString("reference_no"),
                        rs.getString("title"),
                        CaseType.valueOf(rs.getString("case_type")),
                        CaseStatus.valueOf(rs.getString("status")),
                        rs.getObject("opened_on", LocalDate.class),
                        rs.getObject("updated_at", OffsetDateTime.class).toInstant());
                })
                .list();
        long total = counted[0] >= 0 ? counted[0]
                : jdbc.sql("select count(*) from legal_case c" + where).params(params).query(Long.class).single();
        return new PageResponse<>(items, page, size, total, (int) ((total + size - 1) / size));
    }

    /** The validated {@code sort} parameter as SQL; only whitelisted columns ever reach the statement. */
    private static String orderBy(String sort) {
        if (sort == null) {
            return " order by created_at desc, id";
        }
        String[] parts = sort.split(",");
        String column = SORT_COLUMNS.get(parts[0]);
        if (column == null) {
            throw new IllegalArgumentException("unsupported sort field " + parts[0]);
        }
        String direction = parts.length > 1 && parts[1].equals("desc") ? "desc" : "asc";
        return " order by " + column + " " + direction + ", id";
    }

    Optional<LegalCase> find(UUID id) {
        return jdbc.sql("select " + COLUMNS + " from legal_case where id = :id").param("id", id)
                .query(CaseRepository::row).optional();
    }

    boolean exists(UUID id) {
        return jdbc.sql("select exists (select 1 from legal_case where id = :id)").param("id", id)
                .query(Boolean.class).single();
    }

    /** Keeps the registrar's decision that a case differs from one it resembles (section 3); nothing is merged. */
    void recordDuplicateDecision(UUID caseId, DuplicateCheck.Match match, String note, UUID actor) {
        jdbc.sql("""
                        insert into case_duplicate_hint (case_id, other_case_id, kind, reasons, decision, note, decided_by)
                        values (:case, :other, :kind, :reasons, 'DISTINCT', :note, :actor)""")
                .param("case", caseId).param("other", match.caseId()).param("kind", match.kind())
                .param("reasons", String.join(",", match.reasons())).param("note", note).param("actor", actor).update();
    }

    boolean isActiveAuthorityUnit(UUID unit) {
        return jdbc.sql("select exists (select 1 from org_unit where id = :id and tree = 'AUTHORITY' and active)")
                .param("id", unit).query(Boolean.class).single();
    }

    boolean referenceNoTaken(String referenceNo) {
        return jdbc.sql("select exists (select 1 from legal_case where lower(reference_no) = lower(:referenceNo))")
                .param("referenceNo", referenceNo).query(Boolean.class).single();
    }

    /** The next number of {@code year}; the counter row stays locked until the calling transaction ends. */
    int nextReferenceNumber(int year) {
        return jdbc.sql("""
                        insert into case_reference_counter (year, last_number) values (:year, 1)
                        on conflict (year) do update set last_number = case_reference_counter.last_number + 1
                        returning last_number""")
                .param("year", year).query(Integer.class).single();
    }

    private static LegalCase row(ResultSet rs, int rowNum) throws SQLException {
        return new LegalCase(
                rs.getObject("id", UUID.class),
                rs.getString("reference_no"),
                rs.getString("title"),
                CaseType.valueOf(rs.getString("case_type")),
                rs.getString("subject"),
                rs.getObject("opened_on", LocalDate.class),
                CaseStatus.valueOf(rs.getString("status")),
                rs.getLong("version"),
                rs.getObject("created_at", OffsetDateTime.class).toInstant(),
                rs.getObject("created_by", UUID.class),
                rs.getObject("updated_at", OffsetDateTime.class).toInstant(),
                rs.getObject("updated_by", UUID.class),
                rs.getString("automated_no"),
                optional(rs.getString("authority_position"), Side::valueOf),
                optional(rs.getString("financial_impact"), FinancialImpact::valueOf),
                rs.getBigDecimal("financial_amount"),
                member(rs, "primary_member_id", "primary_member_name"),
                member(rs, "alternate_member_id", "alternate_member_name"),
                rs.getString("confidentiality"),
                rs.getObject("owning_unit_id", UUID.class),
                new CaseDetails(rs.getString("chamber"), rs.getObject("received_on", LocalDate.class),
                        rs.getObject("referring_unit_id", UUID.class), rs.getString("referred_by"),
                        rs.getString("facts"), rs.getBigDecimal("claimed_amount"), rs.getString("importance"),
                        rs.getString("internal_notes")));
    }

    private static <T> T optional(String value, java.util.function.Function<String, T> parse) {
        return value == null ? null : parse.apply(value);
    }

    private static MemberRef member(ResultSet rs, String id, String name) throws SQLException {
        UUID memberId = rs.getObject(id, UUID.class);
        return memberId == null ? null : new MemberRef(memberId, rs.getString(name));
    }
}
